package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.provider.OpenableColumns;import android.widget.*;import java.io.*;import java.util.concurrent.*;
/** Explicit private HGT import. No download, device position or object altitude edits. */
public final class DemActivity extends Activity {
 private long project;private String expected;private File raw;private String sourceName;private TextView status;private Button open,save,remove;private volatile boolean disposed;private boolean busy,valid=true;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 public static File file(Context c,long project){if(project<=0)throw new IllegalArgumentException("Нужен проект");return new File(c.getFilesDir(),"project_dem_"+project+".rkdem");}
 public static boolean cleanup(Context c,long project){synchronized(LocalRasterStore.class){File target=file(c,project);if(!target.exists())return true;try{try(HgtRaster own=HgtRaster.owned(target,project)){}return LocalRasterStore.remove(target);}catch(IOException e){return false;}}}
 protected void onCreate(Bundle state){super.onCreate(state);project=getIntent().getLongExtra("project",-1);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,8,12,8);root.setBackgroundColor(0xff232d1d);setContentView(root);ScrollView scroll=new ScrollView(this);status=new TextView(this);status.setTypeface(WorkspaceUi.font(this));status.setTextColor(-1);status.setTextSize(17);scroll.addView(status);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));open=button(root,"Открыть локальный HGT",()->pick());save=button(root,"Установить DEM",()->install());remove=button(root,"Убрать DEM",()->remove());button(root,"К карте",()->onBackPressed());save.setEnabled(false);try{expected=LocalRasterStore.stamp(file(this,project));if(file(this,project).isFile())try(HgtRaster r=HgtRaster.owned(file(this,project),project)){status.setText(description(r,"Установлен DEM"));}else status.setText("DEM не установлен.\n\n"+help());}catch(Exception e){valid=false;status.setText("DEM не изменён: "+e.getMessage());open.setEnabled(false);remove.setEnabled(false);}}
 private Button button(LinearLayout root,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTypeface(WorkspaceUi.font(this));b.setAllCaps(false);root.addView(b,new LinearLayout.LayoutParams(-1,WorkspaceUi.dp(this,48)));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private static String help(){return "Один локальный SRTM HGT: N55E037.hgt, 1201² или3601² signed int16 big-endian, WGS84. Высота исходного SRTM в метрах (обычно EGM96), без преобразования вертикального датума. Только высота ручного центра; GPS, скачивания и изменения высот объектов нет. NoData/вне области показываются как отсутствие данных. Профиль выбранного маршрута/контура: редактор геометрии → Действия → Профиль DEM. Отмывка рельефа: карта → Карты → Подложка → Создать рельеф из DEM; заменяет только явно подтверждённый приватный MBTiles.";}
 private static String description(HgtRaster r,String title){return title+": "+r.name+"\n"+r.samples+" × "+r.samples+"\nГраницы: "+r.west+", "+r.south+" — "+(r.west+1)+", "+(r.south+1)+"\n\n"+help();}
 private void pick(){if(!valid)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_LOCAL_ONLY,true);startActivityForResult(i,4601);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=4601||result!=RESULT_OK||data==null||data.getData()==null||busy||!valid)return;Uri uri=data.getData();if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme())){status.setText("Выберите локальный HGT");return;}String name=null;if("content".equals(uri.getScheme()))try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}catch(Exception e){status.setText("Не удалось получить имя HGT: "+e.getMessage());return;}else name=uri.getLastPathSegment();final String filename=name;busy=true;save.setEnabled(false);status.setText("Проверка локального HGT…");worker.execute(()->{File copy=null;String info=null,error=null;try{copy=File.createTempFile("hgt-input-",".tmp",getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(copy)){if(in==null)throw new IOException("Не удалось открыть HGT");byte[] buffer=new byte[65536];long count=0;int n;while((n=in.read(buffer))!=-1){if(disposed)throw new IOException("Импорт отменён");count+=n;if(count>HgtRaster.MAX_RAW)throw new IOException("HGT превышает размер3601² int16");out.write(buffer,0,n);}out.getFD().sync();}try(HgtRaster reader=new HgtRaster(copy,filename)){info=description(reader,"Готов к установке");}if(disposed)throw new IOException("Импорт отменён");}catch(Exception e){error=e.getMessage();if(copy!=null)copy.delete();copy=null;}final File ready=copy;final String text=error==null?info:"DEM не изменён: "+error;runOnUiThread(()->{busy=false;if(disposed){if(ready!=null)ready.delete();return;}if(raw!=null)raw.delete();raw=ready;sourceName=filename;status.setText(text);save.setEnabled(raw!=null);});});}
 private void install(){if(raw==null||!valid)return;busy=true;save.setEnabled(false);File source=raw;String name=sourceName;worker.execute(()->{File prepared=null;String error=null;try{prepared=File.createTempFile("hgt-owned-",".tmp",getFilesDir());HgtRaster.prepare(source,name,prepared,project);try(HgtRaster check=HgtRaster.owned(prepared,project)){}synchronized(LocalRasterStore.class){if(disposed)throw new IOException("Импорт отменён");ProjectStore store=new ProjectStore(this);try{if(!store.exists(project))throw new IOException("Проект удалён");}finally{store.close();}LocalRasterStore.replace(prepared,file(this,project),expected);prepared=null;expected=LocalRasterStore.stamp(file(this,project));}}catch(Exception e){error=e.getMessage();}finally{if(prepared!=null)prepared.delete();}final String failed=error;runOnUiThread(()->{busy=false;if(disposed)return;if(failed!=null){status.setText("DEM не изменён: "+failed);save.setEnabled(true);}else{setResult(RESULT_OK);try(HgtRaster r=HgtRaster.owned(file(this,project),project)){status.setText(description(r,"Установлен DEM"));}catch(IOException e){status.setText(e.getMessage());}}});});}
 private void remove(){if(!valid||!file(this,project).isFile())return;AlertDialog dialog=new AlertDialog.Builder(this).setMessage("Убрать приватный DEM этого проекта? Исходный HGT, карты, KML и вложения сохранятся.").setPositiveButton("Убрать",(d,w)->{try{synchronized(LocalRasterStore.class){try(HgtRaster own=HgtRaster.owned(file(this,project),project)){}LocalRasterStore.remove(file(this,project),expected);expected=LocalRasterStore.stamp(file(this,project));}setResult(RESULT_OK);status.setText("DEM убран.\n\n"+help());}catch(IOException e){status.setText("DEM не изменён: "+e.getMessage());}}).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(d->{for(int id:new int[]{android.R.id.button1,android.R.id.button2,android.R.id.message}){android.view.View v=dialog.findViewById(id);if(v instanceof TextView)((TextView)v).setTypeface(WorkspaceUi.font(this));}});dialog.show();}
 protected void onDestroy(){disposed=true;File source=raw;raw=null;if(source!=null)source.delete();worker.shutdown();super.onDestroy();}
}
